        return '';
      });
      executePlanEntry(makePlan({ framework: 'go', root: 'pkg' }), dir.root, { reportsDir });
      const cmd = String(mockExecSync.mock.calls[0]?.[0] ?? '');
      expect(cmd).toContain('./pkg/...');
      expect(cmd).not.toContain('./...;');
    } finally {
      dir.cleanup();
    }
