        fs.mkdirSync(planDir, { recursive: true });
        fs.writeFileSync(
          path.join(planDir, 'results.json'),
          JSON.stringify({ testResults: [{ name: 'a.test.ts', assertionResults: [] }] }),
          'utf-8',
        );
        const err = new Error('') as Error & { status: number; message: string };
        err.status = 2;
        err.message = '';
        throw err;
