        cleanup();
      }
    });

    it('全 12 handler 中 phase_next 故意省略 run_id → 该条 isError', async () => {
      const { dir, cleanup } = setupTempProject({
        schema: 'spec-driven',
        tests: [{ root: 'src', framework: 'vitest', includes: ['**/*'] }],
