        await client.callTool({
          name: 'archi_decide',
          arguments: withProjectRoot({ action: 'list' }),
        });
        expect(archiDecide.listAdrs).toHaveBeenCalledWith(dir, undefined);

        await client.callTool({
          name: 'archi_decide',
          arguments: withProjectRoot({
            action: 'update',
