    fs.mkdirSync(path.join(dir, '2026-03-02-bad.md'), { recursive: true });

    const result = listAdrs(project.dir);
    expect(result.count).toBe(1);
    expect(result.adrs[0]?.filename).toBe('2026-03-01-good.md');
  });
});

