  it('detectPowerShellWrite — Export-CliXml 写入 eval.json 返回 deny', () => {
    mockReadFileSync.mockReturnValue(
      JSON.stringify({
        tool_name: 'PowerShell',
        tool_input: { command: 'Get-Process | Export-CliXml openspec/changes/test/eval.json' },
      }),
    );
