describe('captureStderr 辅助函数', () => {
  beforeEach(() => {
    resetMocks();
  });

  it('captureStderr 可捕获 stderr 输出并在 restore 后恢复', () => {
    const [getCaptured, restore] = captureStderr();
    process.stderr.write('captured content');
