/**
 * 集成测试: CLI reportsDir → summary.json / plan report.json
 */

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';

import { beforeEach, describe, expect, it, vi } from 'vite-plus/test';

import { runTestExecution } from '../../src/commands/test-execution';
import type { ExecutionResult } from '../../src/lib/test-runner';
import type { TestPlan } from '../../src/schemas';

const mockDetectFrameworks = vi.fn();
const mockExecutePlanEntry = vi.fn();

vi.mock('../../src/commands/test-detect-frameworks', () => ({
  runTestDetectFrameworks: (...args: unknown[]) => mockDetectFrameworks(...args),
}));

vi.mock('../../src/lib/test-runner', () => ({
  executePlanEntry: (...args: unknown[]) => mockExecutePlanEntry(...args),
}));

function createTempProject(): { root: string; cleanup: () => void } {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'cli-test-execution-'));
  fs.mkdirSync(path.join(root, 'openspec'), { recursive: true });
  fs.writeFileSync(
    path.join(root, 'openspec', 'config.json'),
    JSON.stringify({ schema: 'spec-driven', tests: [{ root: '.', framework: 'vitest' }] }),
    'utf-8',
  );
  return { root, cleanup: () => fs.rmSync(root, { recursive: true, force: true }) };
}

function makePlan(overrides: Partial<TestPlan> = {}): TestPlan {
  return {
    cwd: '.',
    root: '.',
    framework: 'vitest',
    coverage_format: 'istanbul',
    coverage_output: 'coverage-summary.json',
    mutation_cwd: '.',
    mutation_script: null,
    script: {
      shell: 'npx vitest run --outputFile={results_file} {files}',
      cmd: 'npx vitest run --outputFile={results_file} {files}',
    },
    ...overrides,
  };
}

function makeResult(overrides: Partial<ExecutionResult> = {}): ExecutionResult {
  return {
    framework: 'vitest',
    exitCode: 0,
    testCases: [{ name: 't1', status: 'passed', durationMs: 10 }],
    coverage: null,
    mutation: null,
    durationMs: 100,
    testFiles: ['a.test.ts'],
    sourceFiles: ['a.ts'],
    planId: 'vitest',
    reportDir: '',
    ...overrides,
  };
}

describe('CLI 新报告布局 — 无 change', () => {
  beforeEach(() => {
    mockDetectFrameworks.mockReset();
    mockExecutePlanEntry.mockReset();
    vi.spyOn(console, 'log').mockImplementation(() => {});
  });

  it('无 change：写入 reports/test/summary.json 与 reports/test/vitest/report.json', async () => {
    const project = createTempProject();
    try {
      mockDetectFrameworks.mockReturnValue({ detected: [], plan: [makePlan()] });
      mockExecutePlanEntry.mockImplementation((_entry, _projectRoot, options) => {
        const reportDir = path.join(options.reportsDir, 'vitest');
        return makeResult({ reportDir, planId: 'vitest' });
      });

      const exitCode = await runTestExecution({ projectRoot: project.root });
      expect(exitCode).toBe(0);

      const summaryPath = path.join(project.root, 'reports', 'test', 'summary.json');
      const reportPath = path.join(project.root, 'reports', 'test', 'vitest', 'report.json');
      expect(fs.existsSync(summaryPath)).toBe(true);
      expect(fs.existsSync(reportPath)).toBe(true);
      expect(fs.existsSync(path.join(project.root, 'reports', 'test-execution.json'))).toBe(false);
      expect(fs.existsSync(path.join(project.root, 'reports', 'test', 'vitest.json'))).toBe(false);

      const summary = JSON.parse(fs.readFileSync(summaryPath, 'utf-8'));
      expect(Array.isArray(summary.plans)).toBe(true);
      expect(summary.plans[0].id).toBe('vitest');
      expect(summary.plans[0].path.replace(/\\/g, '/')).toMatch(/reports\/test\/vitest$/);
    } finally {
      project.cleanup();
    }
  });

  it('execute 半失败仍写 report.json，summary.plans 含该 plan 的 path', async () => {
    const project = createTempProject();
    try {
      mockDetectFrameworks.mockReturnValue({ detected: [], plan: [makePlan()] });
      mockExecutePlanEntry.mockImplementation((_e, _r, options) =>
        makeResult({
          exitCode: 1,
          error: 'failed',
          testCases: [{ name: 't', status: 'failed', errorMessage: 'x' }],
          reportDir: path.join(options.reportsDir, 'vitest'),
        }),
      );

      const exitCode = await runTestExecution({ projectRoot: project.root });
      expect(exitCode).toBe(1);
      const summary = JSON.parse(
        fs.readFileSync(path.join(project.root, 'reports', 'test', 'summary.json'), 'utf-8'),
      );
      expect(summary.plans).toHaveLength(1);
      expect(summary.plans[0].path.replace(/\\/g, '/')).toContain('reports/test/vitest');
      expect(
        fs.existsSync(path.join(project.root, 'reports', 'test', 'vitest', 'report.json')),
      ).toBe(true);
    } finally {
      project.cleanup();
    }
  });

  it('多 directory plan：plugins_dev-team_bin_vite-plus/report.json 目录 id 无 .json', async () => {
    const project = createTempProject();
    try {
      mockDetectFrameworks.mockReturnValue({
        detected: [],
        plan: [
          makePlan(),
          makePlan({
            cwd: 'plugins/dev-team/bin',
            root: 'plugins/dev-team/bin',
            framework: 'vite-plus',
            coverage_format: 'istanbul',
          }),
        ],
      });
      mockExecutePlanEntry.mockImplementation((entry, _r, options) => {
        const planId =
          entry.root === '.'
            ? entry.framework
            : `${entry.root.replace(/[\\/]/g, '_')}_${entry.framework}`;
        return makeResult({
          framework: entry.framework,
          planId,
          reportDir: path.join(options.reportsDir, planId),
        });
      });

      await runTestExecution({ projectRoot: project.root });
      const nested = path.join(
        project.root,
        'reports',
        'test',
        'plugins_dev-team_bin_vite-plus',
        'report.json',
      );
      expect(fs.existsSync(nested)).toBe(true);
      const summary = JSON.parse(
        fs.readFileSync(path.join(project.root, 'reports', 'test', 'summary.json'), 'utf-8'),
      );
      expect(
        summary.plans.some((p: { id: string }) => p.id === 'plugins_dev-team_bin_vite-plus'),
      ).toBe(true);
    } finally {
      project.cleanup();
    }
  });
});

describe('CLI 新报告布局 — 有 change', () => {
  beforeEach(() => {
    mockDetectFrameworks.mockReset();
    mockExecutePlanEntry.mockReset();
    vi.spyOn(console, 'log').mockImplementation(() => {});
  });

  it('change 专属 …/reports/test/summary.json；plans[].path 含前缀', async () => {
    const project = createTempProject();
    try {
      mockDetectFrameworks.mockReturnValue({ detected: [], plan: [makePlan()] });
      mockExecutePlanEntry.mockImplementation((_e, _r, options) =>
        makeResult({ reportDir: path.join(options.reportsDir, 'vitest') }),
      );
      await runTestExecution({ projectRoot: project.root, change: 'foo' });
      const summaryPath = path.join(
        project.root,
        'openspec',
        'changes',
        'foo',
        'reports',
        'test',
        'summary.json',
      );
      expect(fs.existsSync(summaryPath)).toBe(true);
      const summary = JSON.parse(fs.readFileSync(summaryPath, 'utf-8'));
      expect(summary.plans[0].path.replace(/\\/g, '/')).toMatch(
        /^openspec\/changes\/foo\/reports\/test\//,
      );
    } finally {
      project.cleanup();
    }
  });

  it('change 名含特殊字符时路径仍可创建或被拒绝', async () => {
    const project = createTempProject();
    const changeName = 'my-change.v2 with spaces';
    try {
      mockDetectFrameworks.mockReturnValue({ detected: [], plan: [makePlan()] });
      mockExecutePlanEntry.mockImplementation((_e, _r, options) =>
        makeResult({ reportDir: path.join(options.reportsDir, 'vitest') }),
      );

      let created = false;
      let rejected = false;
      try {
        const exitCode = await runTestExecution({
          projectRoot: project.root,
          change: changeName,
        });
        const summaryPath = path.join(
          project.root,
          'openspec',
          'changes',
          changeName,
          'reports',
          'test',
          'summary.json',
        );
        if (fs.existsSync(summaryPath) && exitCode === 0) {
          created = true;
          const summary = JSON.parse(fs.readFileSync(summaryPath, 'utf-8'));
          const planPath = String(summary.plans[0].path).replace(/\\/g, '/');
          expect(planPath).toContain(`openspec/changes/${changeName}/reports/test/`);
        } else {
          rejected = true;
        }
      } catch {
        rejected = true;
      }

      // 与现实现一致：要么成功落盘（含特殊字符路径），要么被拒绝
      expect(created || rejected).toBe(true);
    } finally {
      project.cleanup();
    }
  });
});

/**
 * 集成测试: detect 占位符 → execute 展开 → reportDir 产物
 */

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';

import { afterEach, beforeEach, describe, expect, it, vi } from 'vite-plus/test';

const mockExecSync = vi.fn();
vi.mock('child_process', () => ({
  execSync: (...args: unknown[]) => mockExecSync(...args),
}));

import { runTestDetectFrameworks } from '../../src/commands/test-detect-frameworks';
import { executePlanEntry } from '../../src/lib/test-runner';

function createTempProject(framework: string): { root: string; cleanup: () => void } {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'cli-placeholders-'));
  fs.mkdirSync(path.join(root, 'openspec'), { recursive: true });
  fs.writeFileSync(
    path.join(root, 'openspec', 'config.json'),
    JSON.stringify({ schema: 'spec-driven', tests: [{ root: '.', framework }] }),
    'utf-8',
  );
  return { root, cleanup: () => fs.rmSync(root, { recursive: true, force: true }) };
}

describe('占位符延迟展开', () => {
  beforeEach(() => {
    mockExecSync.mockReset();
    vi.spyOn(console, 'log').mockImplementation(() => {});
  });
  afterEach(() => vi.restoreAllMocks());

  it('detect 后 script 含未展开 {results_file}/{report_dir}/{config_args}', () => {
    const project = createTempProject('jest');
    try {
      const plan = runTestDetectFrameworks({ projectRoot: project.root }).plan[0];
      expect(plan.script.shell).toContain('{results_file}');
      expect(plan.script.shell).toContain('{report_dir}');
      expect(plan.script.shell).toContain('{config_args}');
      expect(plan.script.shell).not.toMatch(/reports[/\\]test[/\\]/);
    } finally {
      project.cleanup();
    }
  });

  it('detect plan → execute：cmd 不含未替换占位符，planDir 含 results 文件', () => {
    const project = createTempProject('jest');
    try {
      const plan = runTestDetectFrameworks({ projectRoot: project.root }).plan[0];
      expect(plan.script.shell).toContain('{results_file}');
      expect(plan.script.shell).toContain('{report_dir}');
      const reportsDir = path.join(project.root, 'reports', 'test');
      const planDir = path.join(reportsDir, 'jest');
      mockExecSync.mockImplementation(() => {
        fs.mkdirSync(planDir, { recursive: true });
        fs.writeFileSync(
          path.join(planDir, 'results.json'),
          JSON.stringify({
            testResults: [
              {
                name: 'a.test.ts',
                assertionResults: [{ title: 't', fullName: 't', status: 'passed' }],
              },
            ],
          }),
          'utf-8',
        );
        return '';
      });
      const result = executePlanEntry(plan, project.root, { reportsDir });
      const cmd = String(mockExecSync.mock.calls[0][0]);
      expect(cmd).not.toContain('{results_file}');
      expect(cmd).not.toContain('{report_dir}');
      expect(cmd).not.toContain('{config_args}');
      expect(cmd).toContain('results.json');
      expect(fs.existsSync(path.join(planDir, 'results.json'))).toBe(true);
      expect(result.reportDir.replace(/\\/g, '/')).toContain('reports/test/jest');
    } finally {
      project.cleanup();
    }
  });

  it('detect 因 config_flag 校验失败抛错时不进入 execute', () => {
    const project = createTempProject('go');
    try {
      // go 的 config_flag===null，声明 config 时 detect 应抛错
      fs.writeFileSync(
        path.join(project.root, 'openspec', 'config.json'),
        JSON.stringify({
          schema: 'spec-driven',
          tests: [{ root: '.', framework: 'go', config: 'go.mod' }],
        }),
        'utf-8',
      );
      expect(() => runTestDetectFrameworks({ projectRoot: project.root })).toThrow(
        /does not support config injection/,
      );
      expect(mockExecSync).not.toHaveBeenCalled();
    } finally {
      project.cleanup();
    }
  });

  it('detect 不创建 reportDir、不写临时 bunfig', () => {
    const project = createTempProject('bun');
    try {
      runTestDetectFrameworks({ projectRoot: project.root });
      expect(fs.existsSync(path.join(project.root, 'reports', 'test'))).toBe(false);
      expect(fs.readdirSync(project.root).some((n) => n.startsWith('bunfig.dev-team-'))).toBe(
        false,
      );
    } finally {
      project.cleanup();
    }
  });

  it('execute 后 bunfig tempPaths 被删除；用户目录无残留', () => {
    const project = createTempProject('bun');
    try {
      const userBunfig = path.join(project.root, 'bunfig.toml');
      fs.writeFileSync(userBunfig, '[test]\npreload=[]\n', 'utf-8');
      const before = fs.readFileSync(userBunfig, 'utf-8');
      const plan = runTestDetectFrameworks({ projectRoot: project.root }).plan[0];
      const reportsDir = path.join(project.root, 'reports', 'test');
      const seenTemps: string[] = [];
      mockExecSync.mockImplementation(() => {
        const temps = fs
          .readdirSync(project.root)
          .filter((n) => n.startsWith('bunfig.dev-team-'))
          .map((n) => path.join(project.root, n));
        seenTemps.push(...temps);
        fs.mkdirSync(path.join(reportsDir, 'bun'), { recursive: true });
        fs.writeFileSync(path.join(reportsDir, 'bun', 'results.txt'), '1 [PASS] ok\n', 'utf-8');
        return '';
      });
      executePlanEntry(plan, project.root, { reportsDir });
      expect(seenTemps.length).toBeGreaterThan(0);
      for (const t of seenTemps) {
        expect(fs.existsSync(t)).toBe(false);
      }
      expect(fs.readFileSync(userBunfig, 'utf-8')).toBe(before);
    } finally {
      project.cleanup();
    }
  });
});

/**
 * 集成测试: preparePlanArtifacts → 条件重定向 → parsePlanArtifacts
 */

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';

import { afterEach, beforeEach, describe, expect, it, vi } from 'vite-plus/test';

const mockExecSync = vi.fn();
vi.mock('child_process', () => ({
  execSync: (...args: unknown[]) => mockExecSync(...args),
}));

import { getFrameworkConfig } from '../../src/lib/test-framework';
import { executePlanEntry } from '../../src/lib/test-runner';

function createTempProject(): { root: string; cleanup: () => void } {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'cli-redirect-'));
  fs.mkdirSync(path.join(root, 'openspec'), { recursive: true });
  fs.writeFileSync(
    path.join(root, 'openspec', 'config.json'),
    JSON.stringify({ schema: 'spec-driven', tests: [{ root: '.', framework: 'jest' }] }),
    'utf-8',
  );
  return { root, cleanup: () => fs.rmSync(root, { recursive: true, force: true }) };
}

function capturedCmd(): string {
  return String(mockExecSync.mock.calls[0][0]);
}

describe('jest 原生文件通道', () => {
  beforeEach(() => {
    mockExecSync.mockReset();
    vi.spyOn(console, 'log').mockImplementation(() => {});
  });
  afterEach(() => vi.restoreAllMocks());

  it('jest 命令含 --outputFile= 指向 planDir/results.json，无壳层 >', () => {
    const project = createTempProject();
    try {
      const reportsDir = path.join(project.root, 'reports', 'test');
      const cfg = getFrameworkConfig('jest');
      mockExecSync.mockImplementation(() => {
        const planDir = path.join(reportsDir, 'jest');
        fs.writeFileSync(
          path.join(planDir, 'results.json'),
          JSON.stringify({
            testResults: [
              {
                name: 'a.test.ts',
                assertionResults: [{ title: 't', fullName: 't', status: 'passed' }],
              },
            ],
          }),
          'utf-8',
        );
        return '>>> noise\n';
      });
      const result = executePlanEntry(
        {
          cwd: '.',
          root: '.',
          framework: 'jest',
          coverage_format: cfg.coverage_format,
          coverage_output: cfg.coverage_output,
          mutation_cwd: '.',
          mutation_script: null,
          script: {
            shell: cfg.shell.test_execution('99.0.0'),
            cmd: cfg.cmd.test_execution('99.0.0'),
          },
        },
        project.root,
        { reportsDir },
      );
      const cmd = capturedCmd();
      expect(cmd).toContain('--outputFile=');
      expect(cmd).toContain('results.json');
      expect(cmd).not.toMatch(/>\s*"/);
      expect(result.testCases).toHaveLength(1);
    } finally {
      project.cleanup();
    }
  });

  it('exec 返回脏 stdout 时仍从文件解析成功', () => {
    const project = createTempProject();
    try {
      const reportsDir = path.join(project.root, 'reports', 'test');
      const cfg = getFrameworkConfig('jest');
      mockExecSync.mockImplementation(() => {
        fs.writeFileSync(
          path.join(reportsDir, 'jest', 'results.json'),
          JSON.stringify({
            testResults: [
              {
                name: 'a.test.ts',
                assertionResults: [{ title: 't', fullName: 't', status: 'passed' }],
              },
            ],
          }),
          'utf-8',
        );
        return 'NOT JSON AT ALL <<<';
      });
      const result = executePlanEntry(
        {
          cwd: '.',
          root: '.',
          framework: 'jest',
          coverage_format: cfg.coverage_format,
          coverage_output: cfg.coverage_output,
          mutation_cwd: '.',
          mutation_script: null,
          script: {
            shell: cfg.shell.test_execution('99.0.0'),
            cmd: cfg.cmd.test_execution('99.0.0'),
          },
        },
        project.root,
        { reportsDir },
      );
      expect(result.testCases.filter((t) => t.status === 'passed').length).toBe(1);
    } finally {
      project.cleanup();
    }
  });

  it('results.json 缺失 → error，不回退 stdout JSON', () => {
    const project = createTempProject();
    try {
      const reportsDir = path.join(project.root, 'reports', 'test');
      const cfg = getFrameworkConfig('jest');
      mockExecSync.mockReturnValue(
        JSON.stringify({
          testResults: [
            {
              name: 'a.test.ts',
              assertionResults: [{ title: 't', fullName: 't', status: 'passed' }],
            },
          ],
        }),
      );
      const result = executePlanEntry(
        {
          cwd: '.',
          root: '.',
          framework: 'jest',
          coverage_format: cfg.coverage_format,
          coverage_output: cfg.coverage_output,
          mutation_cwd: '.',
          mutation_script: null,
          script: {
            shell: cfg.shell.test_execution('99.0.0'),
            cmd: cfg.cmd.test_execution('99.0.0'),
          },
        },
        project.root,
        { reportsDir },
      );
      expect(result.testCases).toHaveLength(0);
      expect(result.error).toBeTruthy();
    } finally {
      project.cleanup();
    }
  });

  it('coverage 仅从 planDir 读取；cwd 旧 coverage 被忽略', () => {
    const project = createTempProject();
    try {
      const reportsDir = path.join(project.root, 'reports', 'test');
      const oldCov = path.join(project.root, 'coverage');
      fs.mkdirSync(oldCov, { recursive: true });
      fs.writeFileSync(
        path.join(oldCov, 'coverage-summary.json'),
        JSON.stringify({
          total: { lines: { pct: 11 }, branches: { pct: 11 }, functions: { pct: 11 } },
        }),
        'utf-8',
      );
      const cfg = getFrameworkConfig('jest');
      mockExecSync.mockImplementation(() => {
        fs.writeFileSync(
          path.join(reportsDir, 'jest', 'results.json'),
          JSON.stringify({
            testResults: [
              {
                name: 'a.test.ts',
                assertionResults: [{ title: 't', fullName: 't', status: 'passed' }],
              },
            ],
          }),
          'utf-8',
        );
        return '';
      });
      const result = executePlanEntry(
        {
          cwd: '.',
          root: '.',
          framework: 'jest',
          coverage_format: cfg.coverage_format,
          coverage_output: cfg.coverage_output,
          mutation_cwd: '.',
          mutation_script: null,
          script: {
            shell: cfg.shell.test_execution('99.0.0'),
            cmd: cfg.cmd.test_execution('99.0.0'),
          },
        },
        project.root,
        { reportsDir },
      );
      expect(result.coverage).toBeNull();
    } finally {
      project.cleanup();
    }
  });
});

describe('段级重定向框架（bun/go/pytest）', () => {
  beforeEach(() => {
    mockExecSync.mockReset();
    vi.spyOn(console, 'log').mockImplementation(() => {});
  });
  afterEach(() => vi.restoreAllMocks());

  it('bun/go/pytest 测试段命令含 > 且不含 tee；文件解析成功', () => {
    for (const framework of ['bun', 'go', 'pytest'] as const) {
      const project = createTempProject();
      try {
        const reportsDir = path.join(project.root, 'reports', 'test');
        const cfg = getFrameworkConfig(framework);
        mockExecSync.mockReset();
        mockExecSync.mockImplementation(() => {
          const planDir = path.join(reportsDir, framework);
          fs.mkdirSync(planDir, { recursive: true });
          if (framework === 'go') {
            fs.writeFileSync(
              path.join(planDir, 'results.ndjson'),
              `${JSON.stringify({ Action: 'pass', Test: 'TestA' })}\n`,
              'utf-8',
            );
          } else if (framework === 'bun') {
            fs.writeFileSync(path.join(planDir, 'results.txt'), '1 [PASS] ok\n', 'utf-8');
          } else {
            fs.writeFileSync(
              path.join(planDir, 'results.txt'),
              'tests/test_a.py::test_x PASSED\n',
              'utf-8',
            );
          }
          return '';
        });
        const result = executePlanEntry(
          {
            cwd: '.',
            root: '.',
            framework,
            coverage_format: cfg.coverage_format,
            coverage_output: cfg.coverage_output,
            mutation_cwd: '.',
            mutation_script: null,
            script: {
              shell: cfg.shell.test_execution('99.0.0'),
              cmd: cfg.cmd.test_execution('99.0.0'),
            },
          },
          project.root,
          { reportsDir },
        );
        const cmd = capturedCmd();
        expect(cmd).toMatch(/>\s*"/);
        expect(cmd).not.toMatch(/\|\s*tee\b/);
        expect(result.testCases.length).toBeGreaterThan(0);
      } finally {
        project.cleanup();
      }
    }
  });

  it('结果文件空 → 可诊断失败', () => {
    const project = createTempProject();
    try {
      const reportsDir = path.join(project.root, 'reports', 'test');
      const cfg = getFrameworkConfig('bun');
      mockExecSync.mockImplementation(() => {
        fs.mkdirSync(path.join(reportsDir, 'bun'), { recursive: true });
        fs.writeFileSync(path.join(reportsDir, 'bun', 'results.txt'), '', 'utf-8');
        return '';
      });
      const result = executePlanEntry(
        {
          cwd: '.',
          root: '.',
          framework: 'bun',
          coverage_format: cfg.coverage_format,
          coverage_output: cfg.coverage_output,
          mutation_cwd: '.',
          mutation_script: null,
          script: {
            shell: cfg.shell.test_execution('99.0.0'),
            cmd: cfg.cmd.test_execution('99.0.0'),
          },
        },
        project.root,
        { reportsDir },
      );
      expect(result.error).toBeTruthy();
    } finally {
      project.cleanup();
    }
  });
});

